//! Allowlist sanitizer for raw HTML embedded in Markdown.
//!
//! It runs only on markdown-it's `html_block` / `html_inline` tokens, i.e. the
//! raw HTML the author wrote; markup generated by markdown-it and its plugins
//! never passes through here. A small tokenizer (no DOM dependency) keeps an
//! allowlisted tag/attribute set, rewrites URL attributes and escapes every
//! emitted value, so enabling `html: true` never becomes an XSS surface.

/** Tags kept as-is; unknown tags are unwrapped (their text content survives). */
const ALLOWED_TAGS = new Set([
  'a',
  'abbr',
  'b',
  'blockquote',
  'br',
  'caption',
  'code',
  'col',
  'colgroup',
  'dd',
  'del',
  'details',
  'dfn',
  'div',
  'dl',
  'dt',
  'em',
  'figcaption',
  'figure',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
  'hr',
  'i',
  'img',
  // The task-list plugin emits disabled checkbox inputs as inline HTML.
  'input',
  'ins',
  'kbd',
  'li',
  'mark',
  'ol',
  'p',
  'pre',
  'q',
  's',
  'samp',
  'small',
  'span',
  'strong',
  'sub',
  'summary',
  'sup',
  'table',
  'tbody',
  'td',
  'tfoot',
  'th',
  'thead',
  'tr',
  'u',
  'ul',
  'var',
  'wbr',
])

/** Void elements never receive a closing tag. */
const VOID_TAGS = new Set(['br', 'col', 'hr', 'img', 'input', 'wbr'])

/** Raw-text containers dropped together with their content. */
const DROP_CONTENT_TAGS = new Set(['script', 'style', 'textarea', 'title'])

/** Allowed attributes; `on*`, `style`, `id`, `srcset` and friends are dropped. */
const ALLOWED_ATTRS = new Set([
  'href',
  'src',
  'alt',
  'title',
  'class',
  'colspan',
  'rowspan',
  'start',
  'type',
  'checked',
  'disabled',
])

const URL_ATTRS = new Set(['href', 'src'])

const OPEN_TAG = /^<([a-zA-Z][a-zA-Z0-9:-]*)/
const CLOSE_TAG = /^<\/\s*([a-zA-Z][a-zA-Z0-9:-]*)\s*>/
const ATTR_NAME_END = /[\s=/>]/

function escapeAttr(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
}

/** Drop C0 controls so a split scheme (`java\nscript:`) cannot slip through. */
function stripControls(value: string): string {
  let out = ''
  for (const char of value) {
    const code = char.charCodeAt(0)
    if (code > 0x1f && code !== 0x7f) out += char
  }
  return out
}

/**
 * Explicit allowlist: http(s), mail, tel, notes assets, in-page anchors,
 * protocol-relative paths, relative paths and raster data images. Any other
 * scheme (`javascript:`, `vbscript:`, `file:`, unknown ones) is rejected.
 */
function safeUrl(value: string): string | null {
  const trimmed = value.trim()
  const lower = stripControls(trimmed).toLowerCase()
  if (lower.startsWith('data:')) {
    return /^data:image\/(png|jpe?g|gif|webp|avif);base64,/i.test(lower) ? trimmed : null
  }
  // Anchors and scheme-less relative paths have no scheme to abuse.
  if (lower.startsWith('#') || !lower.includes(':')) return trimmed
  if (/^(https?:|mailto:|tel:)/.test(lower)) return trimmed
  // Notes reference images as `asset:<id>`; the preview swaps in data URLs.
  if (lower.startsWith('asset:')) return trimmed
  return null
}

/** One open tag: allowlist the name, then re-emit cleaned attributes. */
function sanitizeOpenTag(source: string, start: number): { html: string; end: number } {
  let i = start + 1
  const name = OPEN_TAG.exec(source.slice(start))
  if (!name) return { html: '', end: start + 1 }
  const tag = name[1].toLowerCase()
  i += name[0].length - 1 // skip `<` + name
  const kept = ALLOWED_TAGS.has(tag)
  const attrs: string[] = []
  const seen = new Map<string, string>()
  let closed = false

  while (i < source.length) {
    while (i < source.length && /\s/.test(source[i])) i += 1
    if (i >= source.length) break
    if (source[i] === '>') {
      closed = true
      i += 1
      break
    }
    if (source[i] === '/') {
      i += 1
      continue
    }

    const nameStart = i
    while (i < source.length && !ATTR_NAME_END.test(source[i])) i += 1
    const attrName = source.slice(nameStart, i).toLowerCase()
    while (i < source.length && /\s/.test(source[i])) i += 1

    let value = ''
    if (source[i] === '=') {
      i += 1
      while (i < source.length && /\s/.test(source[i])) i += 1
      const quote = source[i]
      if (quote === '"' || quote === "'") {
        i += 1
        const valueStart = i
        while (i < source.length && source[i] !== quote) i += 1
        value = source.slice(valueStart, i)
        if (source[i] === quote) i += 1
      } else {
        const valueStart = i
        while (i < source.length && !/[\s>]/.test(source[i])) i += 1
        value = source.slice(valueStart, i)
      }
    }

    if (!kept || !ALLOWED_ATTRS.has(attrName)) continue
    if (URL_ATTRS.has(attrName)) {
      const url = safeUrl(value)
      if (url === null) continue
      seen.set(attrName, url)
      attrs.push(` ${attrName}="${escapeAttr(url)}"`)
    } else {
      seen.set(attrName, value)
      attrs.push(` ${attrName}="${escapeAttr(value)}"`)
    }
  }

  if (!kept) return { html: '', end: closed ? i : source.length }
  if (tag === 'input') {
    // Only the task-list checkbox is allowed; force it disabled so an author
    // input can never become an interactive control.
    if ((seen.get('type') ?? '').toLowerCase() !== 'checkbox') {
      return { html: '', end: closed ? i : source.length }
    }
    if (!seen.has('disabled')) attrs.push(' disabled')
  }
  return { html: `<${tag}${attrs.join('')}>`, end: closed ? i : source.length }
}

/** Sanitize one raw HTML fragment (block or inline tag) against the allowlist. */
export function sanitizeHtml(raw: string): string {
  let out = ''
  let i = 0
  while (i < raw.length) {
    const lt = raw.indexOf('<', i)
    if (lt < 0) {
      out += raw.slice(i)
      break
    }
    // Text before the tag cannot contain `<`, so it is safe verbatim.
    out += raw.slice(i, lt)

    if (raw.startsWith('<!--', lt)) {
      const end = raw.indexOf('-->', lt + 4)
      i = end < 0 ? raw.length : end + 3
      continue
    }
    if (raw[lt + 1] === '!' || raw[lt + 1] === '?') {
      // Doctype / CDATA / processing instruction: drop the declaration.
      const end = raw.indexOf('>', lt + 2)
      i = end < 0 ? raw.length : end + 1
      continue
    }

    if (raw[lt + 1] === '/') {
      const close = CLOSE_TAG.exec(raw.slice(lt))
      if (!close) {
        out += '&lt;'
        i = lt + 1
        continue
      }
      const tag = close[1].toLowerCase()
      if (ALLOWED_TAGS.has(tag) && !VOID_TAGS.has(tag)) out += `</${tag}>`
      i = lt + close[0].length
      continue
    }

    const parsed = sanitizeOpenTag(raw, lt)
    const tag = OPEN_TAG.exec(raw.slice(lt))?.[1].toLowerCase() ?? ''
    if (DROP_CONTENT_TAGS.has(tag)) {
      const lower = raw.toLowerCase()
      const closeAt = lower.indexOf(`</${tag}`, parsed.end)
      if (closeAt < 0) {
        i = raw.length
      } else {
        const gt = raw.indexOf('>', closeAt)
        i = gt < 0 ? raw.length : gt + 1
      }
      continue
    }
    out += parsed.html
    i = parsed.end
  }
  return out
}
